/* Fonte Arimo (Regular + Bold), subset latino, para o PDF da ata via jsPDF.
   Arimo = Liberation Sans: livre e metricamente identica a Arial (mesmo desenho e
   largura). Embutida porque o nucleo do jsPDF nao cobre UTF-8 pleno; garante acentos
   corretos (a,e,i,o,u com acento, til, cedilha) no Safari e no Chrome. ~57KB. */
(function () {
  if (!window.jspdf || !window.jspdf.jsPDF) return;
  var REG = "";
  var BOLD = "";
  window.jspdf.jsPDF.API.events.push(['addFonts', function () {
    this.addFileToVFS('Arimo-Regular.ttf', REG);
    this.addFont('Arimo-Regular.ttf', 'Arimo', 'normal');
    this.addFileToVFS('Arimo-Bold.ttf', BOLD);
    this.addFont('Arimo-Bold.ttf', 'Arimo', 'bold');
  }]);
})();
